vec3 SkyColors(in float t)
{
    vec3 SkyDarkColor=vec3(61./255.,88./255.,175./255.);
    vec3 SkyMediumColor=vec3(89./255.,124./255.,205./255.);
    vec3 SkyPurple=vec3(128./255.,105./255.,214./255.);
    vec3 SkyOrange=vec3(215./255.,128./215.,101./215.);

     if (t < 0.33) {
        return mix(SkyDarkColor, SkyMediumColor, t / 0.33);
    } else if (t < 0.66) {
        return mix(SkyMediumColor, SkyPurple, (t - 0.33) / 0.33);
    } else {
        return mix(SkyPurple, SkyOrange, (t - 0.66) / 0.34);
    }


}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec3 skyColor = SkyColors(uv.y);
    vec3 col=skyColor;
    fragColor = vec4(col,1.0);
}
